-- ORM-style application CRUD (Laravel/Eloquent, Django, Sequelize generated)
SELECT * FROM `users` WHERE `id` = 1 LIMIT 1;
SELECT `id`, `name`, `email` FROM `users` WHERE `email` = 'a@example.com' AND `deleted_at` IS NULL LIMIT 1;
SELECT * FROM `users` WHERE `id` IN (1, 2, 3, 4) ORDER BY `created_at` DESC;
SELECT * FROM `posts` WHERE `user_id` = 5 ORDER BY `created_at` DESC LIMIT 20 OFFSET 40;
SELECT * FROM `posts` ORDER BY `id` DESC LIMIT 40, 20;
SELECT COUNT(*) AS `aggregate` FROM `posts` WHERE `status` = 'published';
SELECT EXISTS(SELECT * FROM `users` WHERE `email` = 'a@example.com') AS `exists`;
INSERT INTO `users` (`name`, `email`, `password`, `created_at`, `updated_at`) VALUES ('Ann', 'ann@example.com', 'hash', NOW(), NOW());
INSERT INTO `users` (`name`, `email`) VALUES ('A', 'a@x.com'), ('B', 'b@x.com'), ('C', 'c@x.com');
INSERT INTO `user_settings` (`user_id`, `k`, `v`) VALUES (1, 'theme', 'dark') ON DUPLICATE KEY UPDATE `v` = VALUES(`v`);
INSERT INTO `page_views` (`page_id`, `views`) VALUES (10, 1) ON DUPLICATE KEY UPDATE `views` = `views` + 1;
INSERT IGNORE INTO `tags` (`name`) VALUES ('go'), ('sql');
REPLACE INTO `sessions` (`id`, `payload`, `last_activity`) VALUES ('abc', 'data', 1700000000);
INSERT INTO `archive_orders` SELECT * FROM `orders` WHERE `created_at` < '2023-01-01';
INSERT INTO `t1` SET `a` = 1, `b` = 'x';
UPDATE `users` SET `name` = 'Bob', `updated_at` = NOW() WHERE `id` = 7;
UPDATE `posts` SET `views` = `views` + 1 WHERE `id` = 99;
UPDATE `orders` SET `status` = 'shipped' WHERE `id` IN (1, 2, 3) AND `status` = 'paid' LIMIT 100;
UPDATE `products` p JOIN `categories` c ON c.id = p.category_id SET p.active = 0 WHERE c.archived = 1;
UPDATE orders o, customers c SET o.region = c.region WHERE o.customer_id = c.id;
DELETE FROM `sessions` WHERE `last_activity` < UNIX_TIMESTAMP() - 7200;
DELETE FROM `comments` WHERE `post_id` = 3 ORDER BY `id` LIMIT 500;
DELETE o FROM orders o LEFT JOIN customers c ON c.id = o.customer_id WHERE c.id IS NULL;
DELETE FROM a, b USING a INNER JOIN b ON a.id = b.a_id WHERE a.flag = 0;
SELECT `u`.*, `p`.`title` FROM `users` AS `u` INNER JOIN `posts` AS `p` ON `p`.`user_id` = `u`.`id` WHERE `u`.`id` = 1;
SELECT `id` FROM `users` WHERE `id` NOT IN (SELECT `user_id` FROM `bans`);
SELECT * FROM `users` WHERE `created_at` BETWEEN '2024-01-01 00:00:00' AND '2024-12-31 23:59:59';
SELECT * FROM `users` WHERE `name` LIKE '%son' OR `name` NOT LIKE 'A%';
SELECT `id` FROM `users` WHERE `id` > 100 FOR UPDATE;
SELECT * FROM `jobs` WHERE `queue` = 'default' AND `reserved_at` IS NULL ORDER BY `id` LIMIT 1 FOR UPDATE SKIP LOCKED;
SELECT * FROM accounts WHERE id = 1 LOCK IN SHARE MODE;
